                  width: piece.bounds.width,
                  height: piece.bounds.height,
                }}
                onPointerEnter={() => setBuildHovered(true)}
                onPointerLeave={() => setBuildHovered(false)}
                onFocus={() => setBuildHovered(true)}
                onBlur={() => setBuildHovered(false)}
              >
                <span
