            ) : (
              <Art pack={pack} symbol={piece.symbol} />
            )}
          </Group>
        ))}
        <Group matrix={UPGRADE_SCREEN.viewers.matrix}>
          {offers.map((tank, index) => (
            <Group key={`${index}:${tank.id}`} matrix={upgradeCardMatrix(index, offers.length)}>
              <article
                className="upgrade-card"
                data-upgrade-card-frame={hovered === index ? 2 : 1}
                style={{
                  left: bounds.x,
                  top: bounds.y,
                  width: bounds.width,
                  height: bounds.height,
                }}
                onPointerEnter={() => {
                  if (menu.motion.cardInputEnabled) setHovered(index);
                }}
                onPointerLeave={() => {
                  if (!menu.motion.cardInputEnabled) return;
                  setHovered(-1);
                  setEditHovered(-1);
                }}
